import {html, isServer} from 'lit';
import {msg} from '@lit/localize';
import {customElement, state} from 'lit/decorators.js';
import {AIUXWidgetElement, decorators} from '@servicenow/aiux-components-core';
import {createGraphQLClient, RecordAPIKey} from '@servicenow/aiux-components-record';
import {withPlaybookFormContext} from '@servicenow/aiux-components-playbook';

const {category, discoverable} = decorators;
const FORM_EDIT_MODE_DEFAULT = 'default';
const FORM_EDIT_MODE_DISPLAY_ONLY = 'display-only';

// The action key the card fires when the user clicks Complete / any primary action.
// Defined in @servicenow/aiux-components-playbook as SUBMIT_FORM_UI_ACTION_KEY.
const SUBMIT_FORM_UI_ACTION_KEY = 'PLAYBOOK#SUBMIT_FORM_UI_ACTION';

// Reads the `table` variable from a sys_flow_data record's vars list.
const FETCH_TABLE_QUERY = `
  query($sysId: String!) {
    GlideRecord_Query {
      sys_flow_data(sys_id: $sysId) {
        _results {
          vars {
            variables {
              variableName
              variableValue
            }
          }
        }
      }
    }
  }
`;

// Marks the sys_flow_data record COMPLETE and records the created record's sys_id.
const COMPLETE_FLOW_MUTATION = `
  mutation($sysId: String!, $recordCreated: String!, $table: String!) {
    GlideRecord_Mutation {
      update_sys_flow_data(sys_id: $sysId, state: "COMPLETE", vars: [
        {variableName: "record_created", variableValue: $recordCreated},
        {variableName: "table", variableValue: $table}
      ]) {
        state { value }
      }
    }
  }
`;

const gql = createGraphQLClient();

/**
 * Create-record activity renderer for playbook cards (SDK-built widget).
 *
 * Reads a `table` variable from the linked sys_flow_data record, then renders
 * a blank (sys_id = -1) form for that table. When the user clicks Complete,
 * the card fires PLAYBOOK#SUBMIT_FORM_UI_ACTION. Our hook saves the form and
 * captures the new record's sys_id, then mutates the sys_flow_data record to
 * COMPLETE — mirroring the seismic card-create-record behaviour.
 *
 * NOTE: Defines static playbook_hooks directly, which overrides withPlaybookFormContext's
 * built-in hooks. The mixin's hook is replicated here for the submit action.
 *
 * Activity props (host-assigned, each a {value} object):
 *   - associated_record : sys_id of the sys_flow_data record
 *   - associated_table  : must be sys_flow_data (sufficiency guard)
 *   - form_view         : (optional) form view to scope visible fields
 *
 * @element playbook-create-record
 */
@discoverable(true)
@category('platform')
@customElement('playbook-create-record')
export default class PlaybookCreateRecord extends withPlaybookFormContext(
  AIUXWidgetElement
) {
  static ssr = false;

  // Overrides the mixin's wildcard hook. Handles the submit action by saving
  // the form and capturing the newly-created record's sys_id right after save —
  // before any re-render can swap out the RecordContext reference.
  static playbook_hooks = {
    [SUBMIT_FORM_UI_ACTION_KEY]: {
      before: async function ({action}) {
        if (!action?.formFieldsRequired) return null;
        const formApi = this._formApi;
        if (!formApi)
          return {blocked: true, errors: [msg('Form not ready — please wait.')]};
        const saved = await formApi.save?.();
        // save() returns false on validation failure, undefined on success.
        if (saved === false || saved?.blocked) return {blocked: true, errors: []};
        const newSysId = formApi.sysId;
        if (!newSysId || newSysId === '-1') return {blocked: true, errors: []};
        this._onRecordCreated(newSysId);
        return {handled: true, result: {ok: true}};
      }
    }
  };

  static properties = {
    associated_record: {type: Object},
    associated_table: {type: Object},
    form_view: {type: Object}
  };

  @state() _table = '';
  @state() _loading = true;
  @state() _error = false;
  @state() _createdSysId = '';

  _lastFetchKey = '';
  _completionFired = false;

  get _isDirty() {
    return this._formApi?.isDirty?.() ?? false;
  }

  connectedCallback() {
    super.connectedCallback();
    this._pushState();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    this._lastPushedState = undefined;
  }

  updated(changedProperties) {
    super.updated(changedProperties);
    if (isServer) return;
    this._fetchTableIfNeeded();
    this._pushState();
  }

  _fetchTableIfNeeded() {
    const sysId = this.associated_record?.value;
    if (!sysId || sysId === this._lastFetchKey) return;
    this._lastFetchKey = sysId;
    this._loading = true;
    this._error = false;
    this._table = '';
    this._createdSysId = '';
    this._completionFired = false;

    gql
      .query(FETCH_TABLE_QUERY, {sysId})
      .then(({data, errors}) => {
        if (errors?.length) throw new Error(errors[0].message);
        const flowVariables =
          data?.GlideRecord_Query?.sys_flow_data?._results?.[0]?.vars
            ?.variables ?? [];
        const tableVar = flowVariables.find(v => v.variableName === 'table');
        if (!tableVar?.variableValue)
          throw new Error('No table variable found in sys_flow_data.');
        this._table = tableVar.variableValue;
        this._loading = false;
      })
      .catch(() => {
        this._error = true;
        this._loading = false;
      });
  }

  _onRecordCreated(sysId) {
    if (this._completionFired) return;
    this._completionFired = true;
    this._createdSysId = sysId;
    const flowDataSysId = this.associated_record?.value;
    if (!flowDataSysId) return;
    gql
      .mutate(COMPLETE_FLOW_MUTATION, {
        sysId: flowDataSysId,
        recordCreated: sysId,
        table: this._table
      })
      .catch(() => {
        console.error('[playbook-create-record] Failed to complete activity.');
      });
  }

  _pushState() {
    const isDirty = this._isDirty;
    if (isDirty === this._lastPushedState?.isDirty) return;
    this._lastPushedState = {isDirty};
    // Intentionally omit recordContext: the inner aiux-record-provider
    // (table=target, sysId='-1') is owned by this widget, not by the card.
    // Propagating it would make the card overwrite associated_table.
    this.dispatchEvent(
      new CustomEvent('playbook-activity-renderer:update', {
        bubbles: true,
        composed: true,
        detail: {isDirty}
      })
    );
  }

  render() {
    const associated = this.associated_record?.value;

    if (!associated || this.associated_table?.value !== 'sys_flow_data') {
      return html`<p class="text-sm text-base-content/40 italic" role="status">
        ${msg('Configuration Error. Please contact your system administrator.')}
      </p>`;
    }

    if (this._loading) {
      return html`<p class="text-sm text-base-content/40 italic" role="status">
        ${msg('Loading…')}
      </p>`;
    }

    if (this._error || !this._table) {
      return html`<p class="text-sm text-error" role="alert">
        ${msg('There was an error. We ran into an issue, please refresh to attempt to resolve.')}
      </p>`;
    }

    const actCtx = this._activityContext;
    const sysId = this._createdSysId || '-1';
    const editMode =
      this._createdSysId || actCtx?.formReadOnly
        ? FORM_EDIT_MODE_DISPLAY_ONLY
        : FORM_EDIT_MODE_DEFAULT;

    return html`
      <aiux-record-provider
        table=${this._table}
        .sysId=${sysId}
        view=${this.form_view?.value || ''}
        context-id=${actCtx?.activityContextId || ''}
        .requiredAPIs=${[RecordAPIKey.Actions]}
      >
        <aiux-record-form edit-mode=${editMode}></aiux-record-form>
      </aiux-record-provider>
    `;
  }
}
